mapper.select:
SELECT dea.id, dea.inventory_id, dea.drug_id, dea.hospital_id, dea.batch_no, dea.expire_date, dea.days_to_expire, dea.quantity, dea.alert_level, dea.status, dea.created_at, dea.updated_at, d.name AS drug_name, d.code AS drug_code, d.spec, d.unit, h.name AS hospital_name FROM drug_expiry_alert dea LEFT JOIN drug_info d ON dea.drug_id = d.id LEFT JOIN hospital h ON dea.hospital_id = h.id
dea.status = 'ACTIVE' AND dea.hospital_id = #{hospitalId} AND dea.alert_level = #{alertLevel} AND dea.status = #{status}
ORDER BY dea.days_to_expire ASC, dea.created_at DESC
